CREATE OR REPLACE PROCEDURE apply_interest(p_rate NUMBER) IS
  TYPE t_id IS TABLE OF accounts.acct_id%TYPE;
  l_ids t_id;
BEGIN
  SELECT acct_id
  BULK COLLECT INTO l_ids
  FROM accounts;

  FORALL i IN 1 .. l_ids.COUNT
    UPDATE accounts
       SET balance = balance * (1 + p_rate / 100)
     WHERE acct_id = l_ids(i);

  COMMIT;
END apply_interest;

