CREATE OR REPLACE PROCEDURE rename_if_exists(
  p_table VARCHAR2, p_old_col VARCHAR2, p_new_col VARCHAR2
) IS
  l_cnt PLS_INTEGER;
BEGIN
  SELECT COUNT(*)
    INTO l_cnt
    FROM user_tab_columns
   WHERE table_name = UPPER(p_table)
     AND column_name = UPPER(p_old_col);

  IF l_cnt > 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table ||
                      ' RENAME COLUMN ' || p_old_col || ' TO ' || p_new_col;
  ELSE
    DBMS_OUTPUT.PUT_LINE('Column ' || p_old_col || ' not found; no-op');
  END IF;
END rename_if_exists;

