CREATE OR REPLACE PROCEDURE upsert_customer(
  p_cust_id NUMBER, p_cust_name VARCHAR2, p_region_cd VARCHAR2,
  p_result_id OUT NUMBER
) IS
BEGIN
  MERGE INTO customers_upsert t
  USING (SELECT p_cust_id AS cust_id FROM dual) s
  ON (t.cust_id = s.cust_id)
  WHEN MATCHED THEN UPDATE SET
       t.cust_name = p_cust_name, t.region_cd = p_region_cd
  WHEN NOT MATCHED THEN INSERT (cust_id, cust_name, region_cd)
       VALUES (p_cust_id, p_cust_name, p_region_cd);
  p_result_id := p_cust_id;
  COMMIT;
END upsert_customer;
